Definition m3_cells (L : alayout) (m : amem) : Prop :=
     poison_cells m /\ rmap_cells m
  /\ rw_cells asegs m 0xb71e0 [C1 (Z_to_bv 8 1)] /\ rw_cells asegs m 0xb71e4 [C4 (Z_to_bv 64 0)]
  /\ rw_cells asegs m ATP88 [C8 (Z_to_bv 64 ATSD)] /\ rw_cells asegs m ATSD [C8 (Z_to_bv 64 (al_ctx L))]
  /\ rw_cells asegs m (al_ctx L + 152) [C8 (Z_to_bv 64 (al_t L))]
  /\ rw_cells asegs m 0xb4338 [C8 (Z_to_bv 64 (al_space_beg L))]                      (* [comment removed for export] *)
  /\ rw_cells asegs m 0xb4340 [C4 (Z_to_bv 64 4294967295)]                            (* [comment removed for export] *)
  /\ rw_cells asegs m 0xb4348 [C8 (Z_to_bv 64 (al_space_beg L + K_SPACE_SIZE))]       (* [comment removed for export] *)
  /\ rw_cells asegs m 0xb4350 [C1 (Z_to_bv 8 0)].                                      (* [comment removed for export] *)

